@@ -0,0 +1,11 @@
+// The model PATCH endpoint merges the submitted params into the stored ones, so a key
+// the user deletes from a JSON editor would simply be omitted and survive the save.
+// Callers send an explicit null for each key returned here, which the backend treats
+// as "remove this key".
+export const removedJsonKeys = (
+  shown: Record<string, unknown> | null | undefined,
+  edited: Record<string, unknown>,
+): string[] => Object.keys(shown ?? {}).filter((key) => !Object.prototype.hasOwnProperty.call(edited, key));
+
+export const withoutKeys = (params: Record<string, unknown>, keys: readonly string[]): Record<string, unknown> =>
+  Object.fromEntries(Object.entries(params).filter(([key]) => !keys.includes(key)));

