+import Papa from "papaparse";
+
+const BULK_CREATE_USERS_TEMPLATE_FILENAME = "bulk_users_template.csv";
+
+// Column order matches the "Template Column Names" list shown in the Bulk Invite dialog.
+// user_email and user_role are required by the upload validation; the rest are optional.
+export const BULK_CREATE_USERS_TEMPLATE_COLUMNS = [
+  "user_email",
+  "user_role",
+  "teams",
+  "max_budget",
+  "budget_duration",
+  "models",
+] as const;
+
+// Example rows pass the upload validation as-is. teams is left blank because team IDs are
+// checked against the proxy's existing teams and any placeholder would be rejected.
+const EXAMPLE_ROWS: string[][] = [
+  ["john.doe@example.com", "internal_user", "", "100", "30d", "gpt-3.5-turbo,gpt-4"],
+  ["jane.smith@example.com", "proxy_admin_viewer", "", "", "", ""],
+];
+
+export const buildBulkCreateUsersTemplateCsv = (): string =>
+  Papa.unparse({ fields: [...BULK_CREATE_USERS_TEMPLATE_COLUMNS], data: EXAMPLE_ROWS });
+
+export const downloadBulkCreateUsersTemplate = (): void => {
+  const blob = new Blob([buildBulkCreateUsersTemplateCsv()], { type: "text/csv" });
+  const url = window.URL.createObjectURL(blob);
+  const a = document.createElement("a");
+  a.href = url;
+  a.download = BULK_CREATE_USERS_TEMPLATE_FILENAME;
+  document.body.appendChild(a);
+  a.click();
+  document.body.removeChild(a);
+  window.URL.revokeObjectURL(url);
+};

